-- Transactional integration test: all fixture users, rooms and writes roll back.
begin;
create function pg_temp.check(ok boolean, description text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %', description; end if; end $$;
create function pg_temp.denied(statement text, expected text) returns void language plpgsql as $$ declare denied boolean:=false; begin begin execute statement; exception when others then if sqlerrm not like '%'||expected||'%' then raise; end if;denied:=true;end;if not denied then raise exception 'Expected denial: %',expected;end if;end $$;
insert into auth.users(id) select ('f0000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,4)n;
set local role authenticated;
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);
select public.game_create('Recovery SQL fixture','Host');select public.game_support_recovery();
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
select public.game_request((public.game_directory()->0->>'id')::uuid,'Second');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_approve('f0000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select public.game_support_recovery();select public.game_ready(true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);
select public.game_request((public.game_directory()->0->>'id')::uuid,'Third');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_approve('f0000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);select public.game_support_recovery();select public.game_ready(true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_start();
select public.game_publish_snapshot(jsonb_build_object('sequence',7,'state',jsonb_build_object('seed',(public.game_room()->>'seed')::bigint,'ownerId',auth.uid(),'run',jsonb_build_object('banked',jsonb_build_array(1),'huntElapsed',52,'phase','playing','initialPlayerCount',3))));
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000004',true);
select pg_temp.denied('select public.game_recover()','NOT_MEMBER');select pg_temp.denied('select public.game_support_recovery()','NOT_MEMBER');select pg_temp.denied('select public.game_publish_snapshot(''{}'')','NOT_OWNER');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
select pg_temp.check(public.game_recover()#>>'{room,ownerId}'='f0000000-0000-0000-0000-000000000001','fresh owner cannot be displaced');
select pg_temp.check(public.game_recover()#>'{snapshot,state,run,banked}'='[1]'::jsonb,'authenticated recovery includes banked keys');
select pg_temp.check(public.game_recover(true)#>>'{room,ownerEpoch}'='0','guest cannot rotate the owner epoch');
select pg_temp.denied('select game_private.rotate_owner(gen_random_uuid(),auth.uid(),true)','permission denied');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_leave();
select pg_temp.check(public.game_room() is null,'former owner loses membership');select pg_temp.denied('select public.game_publish_snapshot(''{}'')','NOT_OWNER');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
select pg_temp.check(public.game_room()->>'ownerId'=auth.uid()::text,'lowest surviving slot succeeds owner');
select pg_temp.check((public.game_room()->>'ownerEpoch')::integer=1,'owner change increments authority epoch');
select pg_temp.check(public.game_recover()#>>'{snapshot,state,run,huntElapsed}'='52','handoff preserves hunt clock');
select pg_temp.check(public.game_recover()#>>'{snapshot,state,ownerId}'=auth.uid()::text,'checkpoint binds new owner');
select pg_temp.check(public.game_recover()#>>'{snapshot,authority,epoch}'='1','server stamps checkpoint authority');
select pg_temp.denied('select public.game_publish_snapshot(jsonb_build_object(''authority'',jsonb_build_object(''ownerId'',auth.uid(),''epoch'',0)))','INVALID_AUTHORITY');
select pg_sleep(.11);select public.game_publish_snapshot(jsonb_build_object('authority',jsonb_build_object('ownerId',auth.uid(),'epoch',1),'sequence',8,'state',jsonb_build_object('run',jsonb_build_object('banked',jsonb_build_array(1),'huntElapsed',52))));
-- Only this fixture's owner is made stale. No browser supplies heartbeat times.
reset role;
update public.game_lobbies set heartbeat_at=clock_timestamp()-interval '46 seconds' where owner_id='f0000000-0000-0000-0000-000000000002';
set local role authenticated;select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);
select pg_temp.check(public.game_recover()#>>'{room,ownerId}'=auth.uid()::text,'expired owner lease transfers to a current member');
select pg_temp.check((public.game_room()->>'ownerEpoch')::integer=2,'second handoff has a new authority epoch');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select pg_temp.denied('select public.game_recover()','NOT_MEMBER');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000003',true);select pg_temp.check(public.game_recover(true)#>>'{room,ownerEpoch}'='3','same-identity owner reload starts a fresh authority epoch');select public.game_leave();
-- Old clients do not advertise recovery support; preserve their existing leave behaviour.
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_create('Legacy fixture','Host');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select public.game_request((public.game_directory()->0->>'id')::uuid,'Legacy guest');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_approve('f0000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select public.game_ready(true);
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);select public.game_start();select public.game_publish_snapshot('{"sequence":1}');select public.game_leave();
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select pg_temp.check(public.game_room() is null,'legacy room closes on owner leave');
rollback;
